package twinddl

// artifactHeader is the deterministic banner of every generated artifact.
const artifactHeader = `-- GENERATED by cmd/twin-ddl-gen --generate from
-- internal/platform/sqlite/twinddl/twin_tables.sql.
-- DO NOT EDIT — regenerate instead; the parity tests compare this file
-- byte-for-byte against the source (TestTwinSource_GeneratedArtifactsCurrent).
`

// ArtifactCanonical / ArtifactJobsPlane are the generated artifact filenames
// under twinddl/generated/.
const (
	ArtifactCanonical = "twin_canonical.sql"
	ArtifactJobsPlane = "twin_jobs_plane.sql"
)

// GenerateArtifacts renders the two plane projections from twin_tables.sql.
// The canonical artifact is the primary-plane declaration block; the jobs
// artifact is the jobs-plane projection (the pinned divergence rules applied).
// Both are deterministic renderings of the parsed shapes.
func GenerateArtifacts() (map[string]string, error) {
	canonical, err := CanonicalShapes()
	if err != nil {
		return nil, err
	}
	projection, err := JobsPlaneShapes()
	if err != nil {
		return nil, err
	}
	render := func(shapes map[string]TableShape, banner string) string {
		out := artifactHeader + banner
		for _, table := range TwinTables {
			out += RenderCanonical(shapes[table]) + "\n"
		}
		return out
	}
	return map[string]string{
		ArtifactCanonical: render(canonical, "\n-- Canonical declarations (primary plane).\n\n"),
		ArtifactJobsPlane: render(projection, "\n-- Jobs-plane projection (CHECK constraints and three pinned timestamp\n"+
			"-- DEFAULT expressions dropped; see projection.go).\n\n"),
	}, nil
}

// NormalizeDefault canonicalises a DEFAULT expression for cross-package
// comparison (live PRAGMA output vs folded declarations vs the source).
func NormalizeDefault(s string) string {
	return normalizeDefault(s)
}

// NormalizeCheck canonicalises a full "CHECK (...)" clause for cross-package
// comparison.
func NormalizeCheck(expr string) string {
	return normalizeCheck(expr)
}

// NormalizeExpr canonicalises an arbitrary SQL expression (index WHERE
// predicates, default expressions) for cross-package comparison.
func NormalizeExpr(s string) string {
	return normalizeExpr(s)
}
